//! Golden decision vectors (`fixtures/decide/*.json`, generated by the host's TS harness).
//! M1 adds the `decide()` snapshot; for now every fixture input must round-trip the wire types.
use fliks_engine_core::api::{DeviceProfile, MediaInfo, SourceScan, StreamingConfig};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::PathBuf;

fn fixtures() -> Vec<(String, Value)> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/decide");
    let mut out: Vec<_> = std::fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .map(|p| {
            let name = p.file_name().unwrap().to_string_lossy().into_owned();
            (name, serde_json::from_str(&std::fs::read_to_string(&p).unwrap()).unwrap())
        })
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

/// JSON equality where `180` and `180.0` are the same number (JS has one number type).
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| same(v, w)))
        }
        _ => a == b,
    }
}

fn roundtrip<T: Serialize + for<'a> Deserialize<'a>>(name: &str, what: &str, v: &Value) {
    let t: T = serde_json::from_value(v.clone()).unwrap_or_else(|e| panic!("{name}: {what}: {e}"));
    let back = serde_json::to_value(t).unwrap();
    assert!(same(&back, v), "{name}: {what} changed on round trip\n in: {v}\nout: {back}");
}

#[test]
fn fixture_inputs_roundtrip_wire_types() {
    let all = fixtures();
    assert!(!all.is_empty(), "fixtures/decide is empty");
    for (name, f) in &all {
        let input = &f["input"];
        roundtrip::<MediaInfo>(name, "input.info", &input["info"]);
        roundtrip::<DeviceProfile>(name, "input.device", &input["device"]);
        if !input["scan"].is_null() {
            roundtrip::<SourceScan>(name, "input.scan", &input["scan"]);
        }
        serde_json::from_value::<StreamingConfig>(f["config"].clone())
            .unwrap_or_else(|e| panic!("{name}: config: {e}"));
    }
}
